
#[cfg(test)]mod decay71_meteor74_request_development_tests {
    use super::*;
    const OTHER:u32=0x71234567;
    fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.extend([71,74]);w.hp=Some([1,100]);w.mp=Some([1,100]);let mut a=w.own_actor().unwrap().clone();a.id=OTHER;a.incarnation+=10;a.x+=1;w.actors.insert(OTHER,a);w}
    fn wire(w:&World,id:u16)->Vec<u8>{let a=&w.actors[&OTHER];let mut b=vec![20,((id-1)/8)as u8,((id-1)%8)as u8];b.extend(OTHER.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());b}
    #[test]fn both_requests_are_actor_xy_with_no_local_MP_or_status_prediction(){let w=world();let before=serde_json::to_value(&w).unwrap();for id in [71,74]{assert_eq!(request(&w,id,Some(OTHER)).unwrap(),wire(&w,id));assert_eq!(wire(&w,id).len(),11);assert!(request(&w,id,None).is_err());assert!(request(&w,id,Some(w.own_actor().unwrap().id)).is_err());}assert_eq!(serde_json::to_value(&w).unwrap(),before);assert_eq!((reuse_millis(71),client_clock_millis(71)),(500,500));assert_eq!(reuse_millis(74),3000);}
    #[test]fn exact_range_edges_and_stale_targets_do_not_fall_back_to_self(){for(id,range)in[(71,3),(74,10)]{let mut w=world();let own=w.own_actor().unwrap().clone();w.actors.get_mut(&OTHER).unwrap().x=own.x+range;assert!(request(&w,id,Some(OTHER)).is_ok());w.actors.get_mut(&OTHER).unwrap().x+=1;assert!(request(&w,id,Some(OTHER)).is_err());w.actors.remove(&OTHER);assert!(request(&w,id,Some(OTHER)).is_err());}}
    #[test]fn missing_book_MP_dead_target_and_movement_block_reject_before_packet(){for id in [71,74]{let mut w=world();w.learned_skills.remove(&id);assert!(request(&w,id,Some(OTHER)).is_err());w.learned_skills.insert(id);w.mp=Some([0,100]);assert!(request(&w,id,Some(OTHER)).is_err());w.mp=Some([1,100]);w.actors.get_mut(&OTHER).unwrap().dead=true;assert!(request(&w,id,Some(OTHER)).is_err());w.actors.get_mut(&OTHER).unwrap().dead=false;w.movement_blocks.insert(1);assert!(request(&w,id,Some(OTHER)).is_err());}}
    #[test]fn learned_native_menu_rows_preserve_captured_actor_life_and_revision(){use super::super::native_skill_selection::{Model,Target};let mut w=world();let mut m=Model::default();m.sync(7,&w,true);for id in [71,74]{m.select(Some(id)).unwrap();let target=Target::capture(&w,OTHER).unwrap();assert_eq!(m.choice(7,&w,Some(target)).unwrap().target,Some(OTHER));w.actors.get_mut(&OTHER).unwrap().target_revision+=1;assert!(m.choice(7,&w,Some(target)).is_err());}}
}
